import React, {FC, useState} from 'react';
import './SearchForm.scss';
import reset from './reset.svg';
import search from './search.svg';
import {ISearchOptions} from "../../../interfaces/commonInterfaces";

interface SearchFormProps {
    searchOptions: ISearchOptions;
    setSearchOptions: (searchOptions: ISearchOptions) => void;
}

const SearchForm: FC<SearchFormProps> = ({searchOptions, setSearchOptions}) => {
    const [searchInput, setSearchInput] = useState<string>('');
    return (
        <form id="search-form" className={'search-form'} onSubmit={(e) => {
            e.preventDefault();
            setSearchOptions({...searchOptions, search: searchInput});
        }}>
            <label className={"search-bar"}>
                <label className={"search-input"}>
                    <input type="text" placeholder="Type something..." name="search" id="search-input" value={searchInput} onChange={(e) => setSearchOptions({...searchOptions, search: e.target.value})}/>
                    <button type="reset" id="reset-button" onClick={(e) => {setSearchOptions({...searchOptions, search: ""}); setSearchInput('')}}><img src={reset} alt="reset"/></button>
                </label>
                <span className={"vertical-line"}></span>
                <button type="submit" id="search-button"><img src={search} alt="search"/></button>
            </label>
        </form>
    );
};

export default SearchForm;
